@@
   if (message !== undefined) {
     // @ts-expect-error
     issue.message =
       typeof message === 'function'
         ? // @ts-expect-error
           message(issue)
         : message;
   }
+
+  // Add the configured prefix after evaluating the custom message so message
+  // callbacks receive the original, unprefixed message.
+  if (config.messagePrefix !== undefined) {
+    issue.message = `${config.messagePrefix}${issue.message}`;
+  }

