import type {
  BaseIssue,
  BaseSchema,
  Config,
  InferIssue,
  InferOutput,
  MaybeReadonly,
  OutputDataset,
} from '../../types/index.ts';
import { _getStandardProps } from '../../utils/index.ts';
import { getFallback } from '../getFallback/index.ts';

/**
 * Fallback type.
 */
export type Fallback<
  TSchema extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
> =
  | MaybeReadonly<InferOutput<TSchema>>
  | ((
      dataset?: OutputDataset<InferOutput<TSchema>, InferIssue<TSchema>>,
      config?: Config<InferIssue<TSchema>>
    ) => MaybeReadonly<InferOutput<TSchema>>);

/**
 * Fallback predicate type.
 */
export type FallbackPredicate<
  TSchema extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
> = (
  dataset: OutputDataset<InferOutput<TSchema>, InferIssue<TSchema>>,
  config: Config<InferIssue<TSchema>>
) => boolean;

/**
 * Schema with fallback type.
 */
export type SchemaWithFallback<
  TSchema extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
  TFallback extends Fallback<TSchema>,
> = TSchema & {
  /**
   * The fallback value.
   */
  readonly fallback: TFallback;
};

/**
 * Returns a fallback value as output if the input does not match the schema.
 *
 * @param schema The schema to catch.
 * @param fallback The fallback value.
 * @param predicate A predicate that determines whether the fallback is used.
 *
 * @returns The passed schema.
 */
// @__NO_SIDE_EFFECTS__
export function fallback<
  const TSchema extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
  const TFallback extends Fallback<TSchema>,
>(
  schema: TSchema,
  fallback: TFallback,
  predicate?: FallbackPredicate<TSchema>
): SchemaWithFallback<TSchema, TFallback> {
  return {
    ...schema,
    fallback,
    get '~standard'() {
      return _getStandardProps(this);
    },
    '~run'(dataset, config) {
      const outputDataset = schema['~run'](dataset, config);
      return outputDataset.issues &&
        (!predicate || predicate(outputDataset, config))
        ? { typed: true, value: getFallback(this, outputDataset, config) }
        : outputDataset;
    },
  };
}
import type {
  BaseIssue,
  BaseSchema,
  BaseSchemaAsync,
  Config,
  InferInput,
  InferIssue,
  InferOutput,
  MaybePromise,
  MaybeReadonly,
  OutputDataset,
  StandardProps,
  UnknownDataset,
} from '../../types/index.ts';
import { _getStandardProps } from '../../utils/index.ts';
import { getFallback } from '../getFallback/index.ts';

/**
 * Fallback async type.
 */
export type FallbackAsync<
  TSchema extends
    | BaseSchema<unknown, unknown, BaseIssue<unknown>>
    | BaseSchemaAsync<unknown, unknown, BaseIssue<unknown>>,
> =
  | MaybeReadonly<InferOutput<TSchema>>
  | ((
      dataset?: OutputDataset<InferOutput<TSchema>, InferIssue<TSchema>>,
      config?: Config<InferIssue<TSchema>>
    ) => MaybePromise<MaybeReadonly<InferOutput<TSchema>>>);

/**
 * Fallback async predicate type.
 */
export type FallbackAsyncPredicate<
  TSchema extends
    | BaseSchema<unknown, unknown, BaseIssue<unknown>>
    | BaseSchemaAsync<unknown, unknown, BaseIssue<unknown>>,
> = (
  dataset: OutputDataset<InferOutput<TSchema>, InferIssue<TSchema>>,
  config: Config<InferIssue<TSchema>>
) => MaybePromise<boolean>;

/**
 * Schema with fallback async type.
 */
export type SchemaWithFallbackAsync<
  TSchema extends
    | BaseSchema<unknown, unknown, BaseIssue<unknown>>
    | BaseSchemaAsync<unknown, unknown, BaseIssue<unknown>>,
  TFallback extends FallbackAsync<TSchema>,
> = Omit<TSchema, 'async' | '~standard' | '~run'> & {
  /**
   * The fallback value.
   */
  readonly fallback: TFallback;
  /**
   * Whether it's async.
   */
  readonly async: true;
  /**
   * The Standard Schema properties.
   *
   * @internal
   */
  readonly '~standard': StandardProps<
    InferInput<TSchema>,
    InferOutput<TSchema>
  >;
  /**
   * Parses unknown input values.
   *
   * @param dataset The input dataset.
   * @param config The configuration.
   *
   * @returns The output dataset.
   *
   * @internal
   */
  readonly '~run': (
    dataset: UnknownDataset,
    config: Config<BaseIssue<unknown>>
  ) => Promise<OutputDataset<InferOutput<TSchema>, InferIssue<TSchema>>>;
};

/**
 * Returns a fallback value as output if the input does not match the schema.
 *
 * @param schema The schema to catch.
 * @param fallback The fallback value.
 * @param predicate An asynchronous predicate that determines whether the
 * fallback is used.
 *
 * @returns The passed schema.
 */
// @__NO_SIDE_EFFECTS__
export function fallbackAsync<
  const TSchema extends
    | BaseSchema<unknown, unknown, BaseIssue<unknown>>
    | BaseSchemaAsync<unknown, unknown, BaseIssue<unknown>>,
  const TFallback extends FallbackAsync<TSchema>,
>(
  schema: TSchema,
  fallback: TFallback,
  predicate?: FallbackAsyncPredicate<TSchema>
): SchemaWithFallbackAsync<TSchema, TFallback> {
  return {
    ...schema,
    fallback,
    async: true,
    get '~standard'() {
      return _getStandardProps(this);
    },
    async '~run'(dataset, config) {
      const outputDataset = await schema['~run'](dataset, config);
      return outputDataset.issues &&
        (!predicate || (await predicate(outputDataset, config)))
        ? {
            typed: true,
            value: await getFallback(this, outputDataset, config),
          }
        : outputDataset;
    },
  };
}

