import type { BaseIssue, Config } from '../../types/index.ts';

/**
 * The global config type.
 */
export type GlobalConfig = Omit<Config<never>, 'message'>;

// Create global configuration store
let store: GlobalConfig | undefined;

/**
 * Sets the global configuration.
 *
 * @param config The configuration.
 */
export function setGlobalConfig(config: GlobalConfig): void {
  store = { ...store, ...config };
}

/**
 * Returns the global configuration.
 *
 * @param config The config to merge.
 *
 * @returns The configuration.
 */
// @__NO_SIDE_EFFECTS__
export function getGlobalConfig<const TIssue extends BaseIssue<unknown>>(
  config?: Config<TIssue>
): Config<TIssue> {
  // Hint: The configuration is deliberately not constructed with the spread
  // operator for performance reasons
  return {
    lang: config?.lang ?? store?.lang,
    message: config?.message,
    abortEarly: config?.abortEarly ?? store?.abortEarly,
    abortPipeEarly: config?.abortPipeEarly ?? store?.abortPipeEarly,
  };
}

/**
 * Deletes the global configuration.
 */
export function deleteGlobalConfig(): void {
  store = undefined;
}
library/src/storages/globalConfig/globalConfig.test.ts
import { describe, expect, test } from 'vitest';
import type { Config } from '../../types/index.ts';
import {
  deleteGlobalConfig,
  getGlobalConfig,
  type GlobalConfig,
  setGlobalConfig,
} from './globalConfig.ts';

describe('config', () => {
  const initialConfig: Config<never> = {
    lang: undefined,
    message: undefined,
    abortEarly: undefined,
    abortPipeEarly: undefined,
  };

  const customConfig: GlobalConfig = {
    lang: 'en',
    abortEarly: true,
    abortPipeEarly: false,
  };

  test('should be undefined initially', () => {
    expect(getGlobalConfig()).toStrictEqual(initialConfig);
  });

  test('should set and get global config', () => {
    setGlobalConfig(customConfig);
    expect(getGlobalConfig()).toStrictEqual({
      ...initialConfig,
      ...customConfig,
    });
  });

  test('should merge config argument', () => {
    expect(getGlobalConfig({ lang: 'de' })).toStrictEqual({
      ...initialConfig,
      ...customConfig,
      lang: 'de',
    });
  });

  test('should delete global config', () => {
    deleteGlobalConfig();
    expect(getGlobalConfig()).toStrictEqual(initialConfig);
  });
});

